<?php
require_role('admin','guru','kepala_sekolah');
$isTeacher=current_user()['role']==='guru';$modules=$isTeacher?['absensi'=>'Absensi sesi','nilai'=>'Nilai mapel']:(current_user()['role']==='admin'?['kalender'=>'Kalender akademik','siswa'=>'Master siswa (tambah)','guru'=>'Master guru (tambah)','jurusan'=>'Master jurusan (tambah)','ak_ruang'=>'Master ruang / laboratorium (tambah)','kelas'=>'Master kelas (tambah)','mata_pelajaran'=>'Master mata pelajaran (tambah)','anggota'=>'Anggota kelas (tambah)','penugasan'=>'Penugasan guru (tambah)']:['kalender'=>'Kalender akademik']);
if(!empty($isAdminBulk))$modules=array_intersect_key($modules,AK_MASTER_IMPORT_KEYS);
if(!empty($embeddedImportModules))$modules=array_intersect_key($modules,array_flip($embeddedImportModules));
$module=isset($_GET['module'])?input_choice($_GET,'module',array_keys($modules)):array_key_first($modules);
$isMaster=isset(AK_MASTER_IMPORT_KEYS[$module]);
$schedule=null;$scheduleId=null;$date=isset($_GET['tanggal'])?input_date($_GET,'tanggal'):date('Y-m-d');$schedules=$isTeacher?ak_teacher_schedules():[];
$periodId=isset($_GET['id_tahun_ajaran'])?input_id($_GET,'id_tahun_ajaran'):(int)active_period()['id_tahun_ajaran'];
if($isTeacher && $schedules){$scheduleId=isset($_GET['id_jadwal'])?input_id($_GET,'id_jadwal'):(int)$schedules[0]['id_jadwal'];$schedule=ak_schedule($scheduleId);}
$context=['module'=>$module];if($schedule)$context+=['id_jadwal'=>$scheduleId,'tanggal'=>$date];elseif(!$isMaster)$context['id_tahun_ajaran']=$periodId;
?><?php if(!empty($embeddedImportModules)):?><p><a class="button secondary" href="<?=e(ak_link($view,array_diff_key($context,['module'=>true])))?>">Kembali ke modul</a></p><?php endif;?><div class="panel"><h2>Impor dengan preview</h2><p>CSV / XLSX maksimal 5 MB dan 2.000 baris. NIS diperlakukan sebagai teks agar nol di depan terjaga. Impor atomik: jika satu baris gagal, seluruh batch dibatalkan. Kalender impor selalu draft. Isi sheet pertama sesuai header template; gunakan nilai literal, bukan rumus. Tanggal dapat berupa tanggal Excel asli atau teks YYYY-MM-DD. NIS/NIP harus disimpan sebagai teks di Excel.</p><?php if($isMaster):?><p>Bulk upload hanya menambah data. Identitas existing atau ganda ditolak; tidak ada overwrite, kenaikan kelas atau pembuatan akun otomatis. Untuk data berelasi, unggah Jurusan → Kelas → Siswa.</p><a class="button secondary" href="/admin/master.php?table=<?=e($module)?>">Kembali ke Master <?=e(master_definitions()[$module]['label'])?></a><?php endif;?></div>
<form method="get" class="panel form-grid filter"><?php ak_hidden('view',!empty($embeddedImportModules)?$view:'impor');if(!empty($embeddedImportModules))ak_hidden('upload','1');ak_select('module','Modul',$modules,$module);if($schedule):$options=[];foreach($schedules as $s)$options[$s['id_jadwal']]=$s['nama_kelas'].' · '.$s['nama_mapel'].' · '.$s['hari'];ak_select('id_jadwal','Penugasan',$options,$scheduleId);ak_field('tanggal','Tanggal',$date,'date');elseif(!$isMaster):$periods=[];foreach(ak_rows('SELECT t.* FROM tahun_ajaran t JOIN ak_periode a USING(id_tahun_ajaran) WHERE a.terverifikasi=1 ORDER BY t.id_tahun_ajaran DESC') as $p)$periods[$p['id_tahun_ajaran']]=$p['tahun_ajaran'].' '.$p['semester'];ak_select('id_tahun_ajaran','Periode',$periods,$periodId);endif;?><button class="secondary">Pilih konteks</button></form>
<section class="panel"><h2>1. Unduh template</h2><div class="actions"><?php foreach(['csv'=>'CSV','xlsx'=>'Excel'] as $format=>$label):?><a class="button secondary" href="/academic/export.php?<?=e(http_build_query(['kind'=>'template','format'=>$format]+$context))?>">Template <?=e($label)?></a><?php endforeach;?></div><h2>2. Unggah & periksa</h2><form method="post" enctype="multipart/form-data"><?=csrf_field()?><?php ak_hidden('action','impor_preview');foreach($context as $key=>$value)ak_hidden($key,$value);?><label class="field"><span>Berkas CSV / XLSX</span><input type="file" name="berkas" accept=".csv,.xlsx" required></label>
<?php if($module==='absensi'):?><details><summary>Materi untuk pertemuan baru</summary><?php ak_field('pertemuan_ke','Pertemuan ke',1,'number');ak_field('jam_ke','Jam ke','1–2');ak_textarea('materi','Materi pembelajaran');ak_textarea('kegiatan','Kegiatan pembelajaran');?></details><?php elseif($module==='nilai' && $schedule):$rules=[];foreach(ak_rows('SELECT id,versi FROM ak_aturan_nilai WHERE id_guru=? AND id_mapel=? AND id_kelas=? AND id_tahun_ajaran=? ORDER BY versi DESC',[$schedule['id_guru'],$schedule['id_mapel'],$schedule['id_kelas'],$schedule['id_tahun_ajaran']]) as $r)$rules[$r['id']]='Versi '.$r['versi'];ak_select('id_aturan','Aturan penilaian',$rules);endif;ak_field('alasan','Alasan / sumber impor');?><button type="submit">Buat Preview</button></form></section>
<?php if($isMaster&&in_array($module,['siswa','kelas'],true))require __DIR__.'/import_reference.php';?>
<?php $preview=$_SESSION['ak_import']??null;if($preview && $preview['actor']===ak_actor()&&$preview['module']===$module):$previewTotal=count($preview['rows']);[$previewPage,$previewPages,$previewOffset]=crud_page_bounds($previewTotal,20,'preview_page');?><section class="panel" data-import-preview><h2>3. Preview <?=count($preview['rows'])?> baris · <?=e($preview['module'])?></h2><div class="table-scroll"><table><thead><tr><?php foreach(array_keys($preview['rows'][0]) as $key):?><th><?=e($key)?></th><?php endforeach;?></tr></thead><tbody><?php foreach(array_slice($preview['rows'],$previewOffset,crud_page_limit('preview_page')) as $row):?><tr><?php foreach($row as $value):?><td><?=e($value)?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><p class="muted">Menampilkan maksimal <?=crud_page_limit('preview_page')?> baris per halaman; seluruh <?=count($preview['rows'])?> baris divalidasi. Preview berlaku 15 menit dan hanya dapat diterapkan sekali.</p><?php crud_pager($previewPage,$previewPages,$previewTotal,'baris','preview_page');?><form method="post"><?=csrf_field()?><?php ak_hidden('action','impor_commit');ak_hidden('preview_token',$preview['token']);?><label class="check"><input type="checkbox" name="konfirmasi" value="1" required><span>Saya telah memeriksa konteks dan data preview.</span></label><?php if(in_array($preview['module'],['absensi','penugasan'],true)):?><label class="check"><input type="checkbox" name="terverifikasi" value="1"><span><?= $preview['module']==='penugasan'?'Penugasan, periode, dan rentang tanggal telah diverifikasi secara administratif.':'Kehadiran siswa sudah diverifikasi untuk status selain B.' ?></span></label><?php endif;?><button type="submit">Terapkan Impor ke Database</button></form></section><?php endif;?>
